#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import fs from 'node:fs'
import { parseFile, ParseError } from './parser.js'
import { Engine } from './engine.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parseFile(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const engine = new Engine(parsed.policies, parsed.routes)
  const output = []

  if (mode === 'replay') {
    for (const event of parsed.events) {
      const result = engine.process(event.tick, event.key)
      if (result.allow) {
        output.push(`${event.tick} ${event.key} allow`)
      } else {
        output.push(`${event.tick} ${event.key} deny ${result.policy}`)
      }
    }
  } else {
    const perKey = new Map()
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const event of parsed.events) {
      const result = engine.process(event.tick, event.key)
      let stats = perKey.get(event.key)
      if (!stats) {
        stats = { allowed: 0n, denied: 0n }
        perKey.set(event.key, stats)
      }
      if (result.allow) {
        stats.allowed += 1n
        totalAllowed += 1n
      } else {
        stats.denied += 1n
        totalDenied += 1n
      }
    }
    const keys = [...perKey.keys()].sort()
    for (const key of keys) {
      const stats = perKey.get(key)
      output.push(`${key} allowed=${stats.allowed} denied=${stats.denied}`)
    }
    output.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(output.length > 0 ? output.join('\n') + '\n' : '')
  process.exit(0)
}

main()
